local KTool = CS.Engine.Lib.KTool

--- from: Assets/BundleResources/Prefabs/ActivityCakeShop/ActivityCakeShopDrawDialog.prefab > name: Cell
---@class ActivityCakeShopDrawTabCell
---@field Env                           	ActivityCakeShopDrawTabCell             
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field AnimRoot                      	UnityEngine.RectTransform               
---@field Underway                      	UnityEngine.RectTransform               
---@field Finish                        	UnityEngine.RectTransform               
---@field TextDesc                      	UnityEngine.RectTransform               
---@field StatusLock                    	UnityEngine.RectTransform               
---@field FinishDesc                    	UnityEngine.RectTransform               
local ActivityCakeShopDrawTabCell = Class('ActivityCakeShopDrawTabCell')
local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')
local ShadowType = CS.UnityEngine.UI.Shadow

function ActivityCakeShopDrawTabCell:__init()

end

function ActivityCakeShopDrawTabCell:__delete()

end

function ActivityCakeShopDrawTabCell:Awake()
    SetButtonAction(self.AnimRoot.gameObject,Bind(self,self.OnTabCellClick))
    self.shadowComp = self.TextDesc.transform:GetComponent(typeof(ShadowType))
end

function ActivityCakeShopDrawTabCell:SetCallBackAndIndex(cb,index)
    self.callBack = cb
    self.index = index
end

function ActivityCakeShopDrawTabCell:RefreshShow(data)
    self.data = data
    self:RefreshStatusShow()
    self:SetSelectStatus(false)
    CfUtils.FillText(self.TextDesc,self.data.name)
    CfUtils.FillText(self.FinishDesc,self.data.name)
end

function ActivityCakeShopDrawTabCell:RefreshStatusShow()
    local isFinish = self:IsAllShopItemNoStock()
    local isUnLock =  ActivityCakeUtils.GetActivityCakeMgr():IsUnLockShop(self.data.id)
    self.isUnLock = isUnLock
    KTool.SetActive(self.Underway.gameObject,not isFinish)
    KTool.SetActive(self.StatusLock.gameObject,not isUnLock)
    KTool.SetActive(self.Finish.gameObject,isFinish)
end

function ActivityCakeShopDrawTabCell:IsAllShopItemNoStock()
    if self.data.isLimit == 1 then
        return false
    end
    local isOver = true
    for i, v in pairs(self.data.list) do
        if v.currentStock ~= 0 then
            isOver = false
            break
        end
    end
    return isOver
end

function ActivityCakeShopDrawTabCell:OnTabCellClick()
    if not self.isUnLock then
        GameUtils.Toast(localize("抽到特等奖后可进入下一层奖池"))
        return
    end

    if self.callBack then
        self.callBack(self.index)
    end
end

function ActivityCakeShopDrawTabCell:SetSelectStatus(status)
    local aniName = status and "ActivityCakeShopDrawDialog_Cell_Select" or "ActivityCakeShopDrawDialog_Cell_Back"
    local state = status and 2 or 1
    CfUtils.SetUISwitchText(self.TextDesc,state)
    self.shadowComp.enabled = status
    CfUtils.PlayAnimation(self.AnimRoot.gameObject,aniName)
end

function ActivityCakeShopDrawTabCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityCakeShopDrawTabCell